import { defineConfig } from 'vitest/config'
import react from '@vitejs/plugin-react'
import tsconfigPaths from 'vite-tsconfig-paths'
import path from 'path'

// `poolOptions` is valid at runtime for vitest 4.x but the shipped
// `InlineConfig` TS surface is out-of-date. Cast keeps strict tsc happy
// while preserving the runtime isolation behavior.
const testConfig = {
  environment: 'jsdom' as const,
  globals: true,
  setupFiles: ['./tests/setup.ts'],
  pool: 'threads' as const,
  poolOptions: {
    threads: {
